import { randomBytes, scryptSync, timingSafeEqual, createHash } from 'node:crypto';
const SESSION_TTL_MS = 8 * 60 * 60 * 1000;

export function hashPassword(password) {
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, 64).toString('hex');
  return { salt, hash };
}

export function verifyPassword(password, record) {
  const actual = scryptSync(password, record.salt, 64);
  const expected = Buffer.from(record.hash, 'hex');
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

export function tokenHash(token) {
  return createHash('sha256').update(token).digest('hex');
}

export async function createSession(db, user, now = Date.now()) {
  const token = randomBytes(32).toString('hex');
  await db.saveSession({ hash: tokenHash(token), userId: user.id,
    teamId: user.teamId, expiresAt: now + SESSION_TTL_MS });
  return token;
}

export async function authenticate(db, token, now = Date.now()) {
  if (!token) throw new Error('Unauthorized');
  const session = await db.findSession(tokenHash(token));
  if (!session || session.expiresAt <= now) throw new Error('Unauthorized');
  return { id: session.userId, teamId: session.teamId };
}

export async function logout(db, token) {
  await db.deleteSession(tokenHash(token));
}

import { authenticate } from './auth.js';
import { createTask, completeTask, deleteTask } from './tasks.js';
import { allowRequest } from './rate-limit.js';

export function createApi(db) {
  return async function handle(request) {
    // The hosting framework maps thrown errors to HTTP status codes.
    const user = await authenticate(db, request.bearerToken);
    if (!allowRequest(user.id)) return { status: 429, error: 'Rate limit' };
    if (request.method === 'GET' && request.path === '/tasks') {
      return { status: 200, tasks: await db.listTasks(user.teamId) };
    }
    if (request.method === 'POST' && request.path === '/tasks') {
      return { status: 201, task: await createTask(db, user, request.body) };
    }
    if (request.method === 'PATCH' && request.action === 'complete') {
      return { status: 200, task: await completeTask(db, user, request.taskId) };
    }
    if (request.method === 'DELETE') {
      await deleteTask(db, user, request.taskId);
      return { status: 204 };
    }
    return { status: 404, error: 'Not found' };
  };
}

import { audit } from './audit.js';

export function validateTitle(title) {
  if (typeof title !== 'string') throw new Error('Title is required');
  const clean = title.trim();
  if (clean.length < 1 || clean.length > 120) throw new Error('Title must be 1–120 characters');
  return clean;
}

export async function createTask(db, user, input) {
  const title = validateTitle(input.title);
  const task = await db.insertTask({ title, teamId: user.teamId, createdBy: user.id });
  audit('task.created', { taskId: task.id, userId: user.id });
  return task;
}

export async function completeTask(db, user, taskId) {
  const task = await db.completeTask(taskId, user.teamId);
  if (!task) throw new Error('Task not found');
  audit('task.completed', { taskId, userId: user.id });
  return task;
}

export async function deleteTask(db, user, taskId) {
  const deleted = await db.softDeleteTask(taskId, user.teamId);
  if (!deleted) throw new Error('Task not found');
  audit('task.deleted', { taskId, userId: user.id });
}

// db is a PostgreSQL pool; all values use positional parameters.
export function createDatabase(pool) {
  return {
    async listTasks(teamId) {
      const r = await pool.query('SELECT * FROM tasks WHERE team_id = $1 AND deleted_at IS NULL ORDER BY created_at DESC', [teamId]);
      return r.rows;
    },
    async insertTask(task) {
      const r = await pool.query('INSERT INTO tasks(title, team_id, created_by) VALUES ($1, $2, $3) RETURNING *', [task.title, task.teamId, task.createdBy]);
      return r.rows[0];
    },
    async completeTask(id, teamId) {
      const r = await pool.query('UPDATE tasks SET completed = TRUE WHERE id = $1 AND team_id = $2 AND deleted_at IS NULL RETURNING *', [id, teamId]);
      return r.rows[0];
    },
    async softDeleteTask(id, teamId) {
      const r = await pool.query('UPDATE tasks SET deleted_at = NOW() WHERE id = $1 AND team_id = $2 AND deleted_at IS NULL RETURNING id', [id, teamId]);
      return r.rows[0];
    },
    async saveSession(s) {
      await pool.query('INSERT INTO sessions(token_hash, user_id, team_id, expires_at) VALUES ($1, $2, $3, $4)', [s.hash, s.userId, s.teamId, new Date(s.expiresAt)]);
    },
    async findSession(hash) {
      const r = await pool.query('SELECT * FROM sessions WHERE token_hash = $1', [hash]);
      const s = r.rows[0];
      return s && { userId: s.user_id, teamId: s.team_id, expiresAt: new Date(s.expires_at).getTime() };
    },
    async deleteSession(hash) {
      await pool.query('DELETE FROM sessions WHERE token_hash = $1', [hash]);
    }
  };
}

const buckets = new Map();
const WINDOW_MS = 60_000;
const MAX_REQUESTS = 30;

export function allowRequest(userId, now = Date.now()) {
  let bucket = buckets.get(userId);
  if (!bucket || now - bucket.start >= WINDOW_MS) {
    bucket = { start: now, count: 0 };
    buckets.set(userId, bucket);
  }
  bucket.count += 1;
  return bucket.count <= MAX_REQUESTS;
}

// Demo limitation: process-local buckets reset on restart, not shared across replicas.
export function clearBuckets() { buckets.clear(); }

const events = [];
export function audit(action, ids) {
  // Only IDs are retained; never task titles, credentials or session tokens.
  events.push({ action, taskId: ids.taskId, userId: ids.userId, at: Date.now() });
  if (events.length > 1000) events.shift();
}
export function readAudit() { return events.map(e => ({ ...e })); }

CREATE TABLE teams (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE users (
  id BIGSERIAL PRIMARY KEY,
  team_id BIGINT NOT NULL REFERENCES teams(id),
  password_salt TEXT NOT NULL,
  password_hash TEXT NOT NULL
);
CREATE TABLE tasks (
  id BIGSERIAL PRIMARY KEY,
  team_id BIGINT NOT NULL REFERENCES teams(id),
  created_by BIGINT NOT NULL REFERENCES users(id),
  title VARCHAR(120) NOT NULL,
  completed BOOLEAN NOT NULL DEFAULT FALSE,
  deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  team_id BIGINT NOT NULL REFERENCES teams(id),
  expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX active_tasks_by_team ON tasks(team_id) WHERE deleted_at IS NULL;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { authenticate, hashPassword, verifyPassword } from '../src/auth.js';

test('expired sessions are rejected', async () => {
  const db = { findSession: async () => ({ expiresAt: 100 }) };
  await assert.rejects(() => authenticate(db, 'demo-token', 101), /Unauthorized/);
});
test('passwords are verified against salted hashes', () => {
  const record = hashPassword('fictional demo passphrase');
  assert.equal(verifyPassword('fictional demo passphrase', record), true);
  assert.equal(verifyPassword('a different passphrase', record), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validateTitle, completeTask } from '../src/tasks.js';

test('rejects empty titles and overly long titles', () => {
  assert.throws(() => validateTitle('   '));
  assert.throws(() => validateTitle('x'.repeat(121)));
  assert.equal(validateTitle(' Ship demo '), 'Ship demo');
});
test('team ID is forwarded to completion query', async () => {
  const db = { completeTask: async (id, teamId) => {
    assert.equal(teamId, 7);
    return id === 3 ? { id, completed: true } : null;
  }};
  await completeTask(db, { id: 1, teamId: 7 }, 3);
  await assert.rejects(() => completeTask(db, { id: 1, teamId: 7 }, 9));
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { allowRequest, clearBuckets } from '../src/rate-limit.js';

test('allows thirty requests per minute per account', () => {
  clearBuckets();
  for (let i = 0; i < 30; i++) assert.equal(allowRequest('account-a', 0), true);
  assert.equal(allowRequest('account-a', 1), false);
  assert.equal(allowRequest('account-b', 1), true);
  assert.equal(allowRequest('account-a', 60_000), true);
});
